 'remove-clip':el=>{checkpoint();const {s,c}=findClip(el.dataset.id);s.clips.splice(s.clips.indexOf(c),1);close();changed();toast('Plan retiré du tableau. Le rush reste dans la bibliothèque.');},
 'whole':()=>{const m=project.media.find(m=>m.id===activeModal.id);$('[name=start]').value=0;$('[name=end]').value=m.duration;},
