document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el)return;const a=actions[el.dataset.act];if(a){try{await a(el);}catch(err){toast(err.message,true);}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=new FormData(f);try{
 if(f.id==='sequence-form'){const title=d.get('title').trim();if(!title)throw new Error('Donnez un nom à cette séquence.');checkpoint();const s=activeModal.id?findSequence(activeModal.id):newSequence(title);Object.assign(s,{title,color:d.get('color'),description:d.get('description').trim(),target:d.get('target')===''?null:Number(d.get('target')),notes:d.get('notes').trim()});if(!activeModal.id)project.sequences.push(s);close();changed();}
 if(f.id==='film-form'){const name=d.get('name').trim();if(!name)throw new Error('Donnez un nom à votre film.');if(activeModal.rename){checkpoint();project.name=name;}else{await save();project=newProject(name);history=[];}close();changed();}
 if(f.id==='media-form'){const m=project.media.find(m=>m.id===activeModal.id),updated={...m,title:d.get('title').trim(),notes:d.get('notes').trim(),path:d.get('path').trim()||m.name,absolutePath:d.get('absolutePath').trim(),duration:Number(d.get('duration')),fps:Number(d.get('fps'))||null,width:Number(d.get('width')),height:Number(d.get('height')),sourceStart:Number(d.get('sourceStart')),hasAudio:d.get('hasAudio')==='true'};if(!updated.title||updated.duration<=0||!Number.isFinite(updated.duration))throw new Error('Titre ou durée originale incorrecte.');if(updated.absolutePath)mediaURL(updated,project.settings);const {c,s}=activeModal.clipId?findClip(activeModal.clipId):{};const nc=c?{...c}:null;if(c)setTrim(nc,updated,Number(d.get('start')),Number(d.get('end')));for(const seq of project.sequences)for(const other of seq.clips)if(other.mediaId===m.id&&other.id!==c?.id&&((other.out??updated.duration)>updated.duration||other.in>=updated.duration))throw new Error('La nouvelle durée invaliderait une coupe déjà définie.');checkpoint();Object.assign(m,updated);if(c){Object.assign(c,nc,{notes:d.get('clipNotes').trim()});const dest=d.get('destination');if(dest!==s.id)moveClip(project,c.id,dest,findSequence(dest).clips.length);}close();changed();}
 if(f.id==='export-form'){const settings={basePath:d.get('basePath').trim(),fps:d.get('fps'),width:Number(d.get('width')),height:Number(d.get('height'))};const next={...project,settings};const xml=makeFCPXML(next);project.settings=settings;save();const exportUrl=URL.createObjectURL(new Blob([xml],{type:'application/octet-stream'}));modal('Votre prémontage est prêt',`<div class="modal-body"><p>FCPXML 1.9 généré : ${project.sequences.length} séquences, ${time(totalDuration(project),true)}. Téléchargez le fichier, puis ouvrez-le dans Final Cut Pro avec Fichier → Importer → XML.</p><a class="download-link" href="${exportUrl}" download="${esc(filename())}.fcpxml">↓ Télécharger le FCPXML</a><p class="hint" style="margin-top:18px">Les fichiers vidéo restent à leur emplacement original. Si nécessaire, utilisez Relier les fichiers dans Final Cut Pro.</p></div>`,`<button data-act="close">Fermer</button>`);setTimeout(()=>URL.revokeObjectURL(exportUrl),600000);}
 }catch(err){const out=$('#form-error');if(out){out.hidden=false;out.textContent=err.message;}else toast(err.message,true);}});
