document.addEventListener('dragstart',e=>{if(e.target.closest('button'))return;const clip=e.target.closest('[data-clip]'),seq=e.target.closest('[data-seq-drag]'),rush=e.target.closest('[data-rush]');drag=clip?{type:'clip',id:clip.dataset.clip}:seq?{type:'sequence',id:seq.dataset.seqDrag}:rush?{type:'rush',id:rush.dataset.rush}:null;if(!drag)return;e.dataTransfer.effectAllowed=drag.type==='rush'?'copy':'move';e.dataTransfer.setData('application/x-quest',JSON.stringify(drag));e.target.classList.add('dragging');});
function clearDrag(){document.querySelectorAll('.drag-over,.drop-before,.drop-after,.sequence-before,.dragging').forEach(e=>e.classList.remove('drag-over','drop-before','drop-after','sequence-before','dragging'));}
document.addEventListener('dragend',()=>{drag=null;clearDrag();});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){if(e.target.closest('#library,#board'))e.preventDefault();return;}if(!drag)return;const seq=e.target.closest('[data-sequence]'),end=e.target.closest('[data-seq-end]');if(e.target.closest('#board'))e.preventDefault();if(seq||end){e.preventDefault();document.querySelectorAll('.drag-over,.drop-before,.drop-after,.sequence-before').forEach(e=>e.classList.remove('drag-over','drop-before','drop-after','sequence-before'));if(drag.type==='sequence'){seq?.classList.add('sequence-before');}else if(seq){seq.classList.add('drag-over');const c=e.target.closest('[data-clip]');if(c&&c.dataset.clip!==drag.id)c.classList.add(e.clientY>c.getBoundingClientRect().top+c.getBoundingClientRect().height/2?'drop-after':'drop-before');}e.dataTransfer.dropEffect=drag.type==='rush'?'copy':'move';const b=$('#board').getBoundingClientRect();if(e.clientX>b.right-45)$('#board').scrollLeft+=14;if(e.clientX<b.left+45)$('#board').scrollLeft-=14;}});
document.addEventListener('drop',async e=>{if(e.dataTransfer.types.includes('Files')&&e.target.closest('#library,#board')){e.preventDefault();const entries=[];async function readEntry(entry,path=''){if(entry.isFile)await new Promise(ok=>entry.file(file=>{entries.push({file,path:path+file.name});ok();},ok));else if(entry.isDirectory){const reader=entry.createReader();while(true){const batch=await new Promise(ok=>reader.readEntries(ok,()=>ok([])));if(!batch.length)break;for(const en of batch)await readEntry(en,path+entry.name+'/');}}}for(const item of e.dataTransfer.items){const entry=item.webkitGetAsEntry?.();if(entry)await readEntry(entry);else if(item.kind==='file'){const file=item.getAsFile();if(file)entries.push({file});}}await importFiles(entries);return;}
 if(!drag)return;e.preventDefault();const seq=e.target.closest('[data-sequence]'),end=e.target.closest('[data-seq-end]');try{if(!seq&&!end)return;checkpoint();if(drag.type==='sequence'){let idx=seq?project.sequences.findIndex(s=>s.id===seq.dataset.sequence):project.sequences.length;moveSequence(project,drag.id,idx);}else if(seq){const s=findSequence(seq.dataset.sequence),target=e.target.closest('[data-clip]');const idx=target?s.clips.findIndex(c=>c.id===target.dataset.clip)+(e.clientY>target.getBoundingClientRect().top+target.getBoundingClientRect().height/2?1:0):s.clips.length;if(drag.type==='rush')addClip(project,s.id,drag.id,idx);else moveClip(project,drag.id,s.id,idx);}changed();}catch(err){toast(err.message,true);}finally{drag=null;clearDrag();}});
