mountStudio({project:()=>project,films:()=>[project,...projects.filter(p=>p.id!==project.id)],mediaUploaded,save,checkpoint,toast,saveNow:()=>actions['save-sync'](),history:historyModal,undo:()=>actions.undo(),projects:()=>actions.projects(),openProject:async next=>{await save();project=next;initialDraft=null;history=[];changed();await hydrate();}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdate();});});return navigator.serviceWorker.ready;}).then(()=>{$('#offline-state').textContent=`v${APP_VERSION} · prêt hors connexion`;}).catch(()=>toast('Le mode hors connexion n’a pas pu être activé dans ce navigateur.',true));
// Pointer dragging keeps plan movement consistent across mouse and touch surfaces.
document.addEventListener('pointerdown',e=>{
 const card=e.target.closest('.plan-card');if(!card||e.button!==0||e.target.closest('button,input,textarea,select'))return;
 pointerDrag={id:card.dataset.clip,card,x:e.clientX,y:e.clientY,pointerId:e.pointerId,active:false};
});
document.addEventListener('pointermove',e=>{
 const d=pointerDrag;if(!d||e.pointerId!==d.pointerId)return;
 if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<6)return;
 if(!d.active){d.active=true;d.card.setPointerCapture(e.pointerId);d.card.classList.add('dragging');d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.textContent=mediaTitle(findClip(d.id).m);document.body.append(d.ghost);}
 e.preventDefault();d.ghost.style.left=e.clientX+14+'px';d.ghost.style.top=e.clientY+14+'px';
 document.querySelectorAll('.drag-over,.drop-before,.drop-after').forEach(el=>el.classList.remove('drag-over','drop-before','drop-after'));
 const hit=document.elementFromPoint(e.clientX,e.clientY),seq=hit?.closest('[data-sequence]');if(seq){seq.classList.add('drag-over');const target=hit.closest('.plan-card');if(target&&target.dataset.clip!==d.id)target.classList.add(e.clientY>target.getBoundingClientRect().top+target.getBoundingClientRect().height/2?'drop-after':'drop-before');}
 const b=$('#board').getBoundingClientRect();if(e.clientX>b.right-35)$('#board').scrollLeft+=12;if(e.clientX<b.left+35)$('#board').scrollLeft-=12;
 const scroller=hit?.closest('.seq-plans');if(scroller){const r=scroller.getBoundingClientRect();if(e.clientY>r.bottom-35)scroller.scrollTop+=8;if(e.clientY<r.top+35)scroller.scrollTop-=8;}
},{passive:false});
function endPointer(e,cancel=false){const d=pointerDrag;if(!d)return;pointerDrag=null;if(d.active){try{d.card.releasePointerCapture(d.pointerId);}catch{}d.ghost.remove();const hit=document.elementFromPoint(e.clientX,e.clientY),seq=hit?.closest('[data-sequence]');if(seq&&!cancel){const s=findSequence(seq.dataset.sequence),target=hit.closest('.plan-card');if(target?.dataset.clip!==d.id){const idx=target?s.clips.findIndex(c=>c.id===target.dataset.clip)+(e.clientY>target.getBoundingClientRect().top+target.getBoundingClientRect().height/2?1:0):s.clips.length;checkpoint();moveClip(project,d.id,s.id,idx);changed();}}clearDrag();}}
document.addEventListener('pointerup',e=>endPointer(e));document.addEventListener('pointercancel',e=>endPointer(e,true));

function showUpdate(){updateReady=true;$('#update-banner').hidden=false;$('#update-banner').innerHTML='<span>Une nouvelle version de QUEST Montage est disponible.</span><button data-act="refresh-app">Actualiser l’atelier</button>';}
async function checkVersion(manual=false){if(!manual&&Date.now()-lastVersionCheck<60000)return;lastVersionCheck=Date.now();try{const response=await fetch('./version.json',{cache:'no-store'});if(!response.ok)return;const data=await response.json();if(data.version!==APP_VERSION){showUpdate();}else if(manual)toast(`QUEST Montage ${APP_VERSION} est à jour.`);if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.getRegistration();await registration?.update();}}catch{if(manual)toast('Hors connexion : la vérification reprendra au retour du réseau.');}}
function cloudState(state){const button=$('#cloud-status');button.dataset.state=state;button.textContent={syncing:'↻ Enregistrement en cours',synced:'✓ Synchronisé à '+new Date().toLocaleTimeString('fr-FR'),pending:'↻ Enregistrement en cours — données ou médias en attente',offline:navigator.onLine===false?'○ Hors connexion':'⚠ Erreur de connexion — nouvel essai automatique',error:'⚠ Erreur — synchronisation indisponible',auth:usesCloudBridge()?'○ Connecter mes films':'○ Connecter mes appareils'}[state];button.title=state==='synced'?'Même compte ChatGPT : films partagés entre vos appareils. Cliquez pour synchroniser.':state==='auth'?'Connexion au même compte nécessaire pour partager les films.':'Vos modifications restent enregistrées sur cet appareil.';}
async function storeCloudRecord(record,options){
 await saveChain.catch(()=>{});
 if(options.kind==='remote'&&Object.hasOwn(options,'expectedFingerprint')){
  const current=project.id===record.id?project:projects.find(p=>p.id===record.id);
  if(!canApplyRemote(current,options.expectedFingerprint)||syncBlocked(record.id,'pull'))return false;
 }
 if(options.kind==='ack'&&project.id===record.id){const sync=record._sync;record=structuredClone(project);record._sync=sync;}
 const oldDraft=initialDraft;const selectRemote=options.kind==='remote'&&oldDraft&&project.id===oldDraft&&!project.media.length&&!project.sequences.length&&!project.storyboard?.shots?.length&&project.name==='Mon premier film';
 const active=project.id===record.id||project.id===options.replaceActive||selectRemote;
 const index=projects.findIndex(p=>p.id===record.id);if(index<0)projects.push(structuredClone(record));else projects[index]=structuredClone(record);
 if(selectRemote){initialDraft=null;projects=projects.filter(p=>p.id!==oldDraft);if(db)await new Promise((ok,no)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').delete(oldDraft);tx.oncomplete=ok;tx.onerror=()=>no(tx.error);});}
 if(active){if(options.kind!=='ack')history=[];project=structuredClone(record);localStorage.setItem('qm-last',record.id);}
 if(db)await put('projects',record);else localStorage.setItem('qm-projects',JSON.stringify(projects));
 if(active&&options.kind!=='ack'&&!$('#modal').open&&!drag&&!pointerDrag){render();await hydrate();}
}
function syncBlocked(id,phase){return id===project.id&&(!!document.querySelector('dialog[open]')||!!drag||!!pointerDrag||(phase==='pull'&&!!document.activeElement?.closest('#story-studio input,#story-studio textarea,#story-studio select')));}
async function startCloudSync(){
 cloudSync=new FilmSync({list:()=>{const all=projects.map(p=>p.id===project.id?project:p);return all.filter(p=>p.id!==initialDraft);},store:storeCloudRecord,onState:cloudState,onConflict:name=>toast('Modifications simultanées : une version « '+name+' » a été conservée.'),blocked:syncBlocked});
 await cloudSync.once();checkVersion();
 setInterval(()=>{if(document.visibilityState==='visible'){cloudSync.once();checkVersion();}},15000);
 window.addEventListener('online',()=>{cloudSync.once();checkVersion();});
 window.addEventListener('quest-cloud-connected',()=>cloudSync.once());
 document.addEventListener('visibilitychange',()=>{clearTimeout(syncTimer);if(document.visibilityState==='hidden')save();cloudSync.once();if(document.visibilityState==='visible')checkVersion();});
 window.addEventListener('pagehide',()=>{clearTimeout(syncTimer);save();cloudSync.once();});
 document.addEventListener('focusout',e=>{if(e.target.closest('#story-studio'))setTimeout(()=>cloudSync.once(),0);});
}
